import csv,re
csv.field_size_limit(10**8)
L={s:list(csv.DictReader(open(f'data/{s}.csv',newline='',encoding='utf-8'))) for s in ['train','validation']}
def sh(t,k=5):
    w=re.findall(r'\w+',t.lower()); return {' '.join(w[i:i+k]) for i in range(max(1,len(w)-k+1))}
T=[(x,sh(x['text'])) for x in L['train']]
out=[]
for v in L['validation']:
    sv=sh(v['text'])
    for t,s in T:
        j=len(sv&s)/len(sv|s)
        if j>=0.2: out.append((round(j,2),v,t))
out.sort(key=lambda z:-z[0])
for j,v,t in out:
    f=lambda x: x['text'].split(chr(10))[0][:70]
    print(j, v['label'],v['message_id'],'|',f(v)); print('     ', t['label'],t['message_id'],'|',f(t))
"

